mapper.select:
SELECT 
FROM task t JOIN template tpl ON tpl.id = t.template_id
WHERE t.id = #{id}

SELECT 
FROM task t JOIN template tpl ON tpl.id = t.template_id
WHERE t.id = #{id} AND t.user_id = #{userId}

SELECT 
FROM task t JOIN template tpl ON tpl.id = t.template_id
WHERE t.user_id = #{userId}
AND t.template_id = #{templateId}
ORDER BY t.created_at DESC, t.id
LIMIT #{limit}
